import { describe, expect, test } from 'bun:test';
import { getPointAtLength, getTotalLength, splitPath } from 'svg-path-commander/util';
import { parseTimingClasses, reverseD, startPoint, timingClasses } from './svg.js';

// Points at evenly spaced fractions of each subpath's length, subpath by subpath.
function trace(d, steps = 16) {
    return splitPath(d).map(subpath => {
        const length = getTotalLength(subpath);
        return Array.from({ length: steps + 1 }, (_, i) => getPointAtLength(subpath, (length * i) / steps));
    });
}

// Asserts that `reversed` draws `original` backwards: subpaths in reverse order,
// and the point at fraction t of each subpath equals the original's at 1 - t
// (within 0.05, the precision of svg-path-commander's length lookup on curves).
function expectReversed(reversed, original) {
    const forward = trace(original);
    const backward = trace(reversed);
    expect(backward).toHaveLength(forward.length);
    backward.forEach((points, i) => {
        const expected = forward.at(-1 - i).toReversed();
        points.forEach((point, j) => {
            expect(point.x).toBeCloseTo(expected[j].x, 1);
            expect(point.y).toBeCloseTo(expected[j].y, 1);
        });
    });
}

describe('reverseD', () => {
    test.each([
        ['open line', 'M1 2 L3 4 L10 -5'],
        ['cubic curves', 'M99.36 333.52 C117.53 172.83 124.72 122.72 134.44 79.05 C143.31 39.31 157.68 22 180.5 22'],
        ['relative and implicit commands', 'm10 10 l5 0 5 5 h-3 v4 c1 2 3 4 5 6'],
        ['quadratic curves and T', 'M0 0 Q10 20 20 0 T40 0'],
        ['arcs with compact flags', 'M10 10 A5 8 30 0110 30 a4 4 0 1 0 8 8'],
        ['several open subpaths', 'M0 0 L10 0 M20 0 L20 10 M30 30 L40 40'],
        ['closed subpath ending away from start', 'M0 0 L10 0 L10 10 Z'],
        ['closed subpath ending at start', 'M0 0 C10 0 10 10 0 10 L0 0 Z'],
        ['closed and open subpaths mixed', 'M0 0 L10 0 L10 10 Z M50 50 L60 50 m5 5 l0 10 z'],
    ])('draws %s backwards', (_, d) => {
        expectReversed(reverseD(d), d);
    });

    test('closed subpaths start at their original start and keep Z', () => {
        const reversed = reverseD('M0 0 L10 0 L10 10 Z M50 50 L60 50 L60 60 Z');
        expect(reversed).toStartWith('M50 50');
        expect(reversed.match(/Z/g)).toHaveLength(2);
        expect(reversed).toEndWith('Z');
    });

    test.each([
        ['l', 'M10 10 L20 10 Z l5 5', 'M10 10 L20 10 Z M10 10 L15 15'],
        ['h and v', 'M10 10 L20 10 Z h5 v5', 'M10 10 L20 10 Z M10 10 L15 10 L15 15'],
        ['c', 'M10 10 C20 10 20 20 30 30 Z c1 2 3 4 5 6', 'M10 10 C20 10 20 20 30 30 Z M10 10 C11 12 13 14 15 16'],
        ['s', 'M10 10 C20 10 20 20 30 30 Z s3 4 5 6', 'M10 10 C20 10 20 20 30 30 Z M10 10 C10 10 13 14 15 16'],
        ['t', 'M10 10 Q20 10 30 30 Z t5 6', 'M10 10 Q20 10 30 30 Z M10 10 Q10 10 15 16'],
        ['a', 'M10 10 L20 10 Z a5 5 0 0 1 10 0', 'M10 10 L20 10 Z M10 10 A5 5 0 0 1 20 10'],
    ])('reverses relative %s after Z from the closed subpath start', (_, d, explicit) => {
        expectReversed(reverseD(d), explicit);
    });

    test('reverses thousands of repeated closed subpaths without losing traversal or joins', () => {
        const count = 4000;
        const triangle = 'l5 0l0 5z';
        const d = 'M10 10' + triangle.repeat(count);
        const reversed = reverseD(d);
        expectReversed(reversed, ('M10 10' + triangle).repeat(count));
        expect(reversed.match(/Z/g)).toHaveLength(count);
        expect(startPoint(d)).toBe('(10.000000, 10.000000)');
    });

    test('carries relative moves and resets smooth control points across closes', () => {
        const d = 'm10 10 l5 0l0 5z m-3 4 l2 0z s3 4 5 6z m-1 -2 t5 6z M30 40l2 3z m1 2 4 5z t3 2';
        const explicit = 'M10 10 L15 10L15 15Z M7 14 L9 14Z M7 14 C7 14 10 18 12 20Z M6 12 Q6 12 11 18Z M30 40L32 43Z M31 42L35 47Z M31 42Q31 42 34 44';
        const reversed = reverseD(d);
        expectReversed(reversed, explicit);
        expect(reversed.match(/Z/g)).toHaveLength(6);
        expect(startPoint('M10 10z m-3 4 l2 0z')).toBe('(7.000000, 14.000000)');
    });

    test.each([
        ['after C with a 0 control coordinate', 'M10 10 C20 0 0 20 10 30 S30 40 40 30', 'M10 10 C20 0 0 20 10 30 C20 40 30 40 40 30'],
        ['after Q', 'M10 10 Q20 0 30 10 S40 30 50 10', 'M10 10 Q20 0 30 10 C30 10 40 30 50 10'],
    ])('reflects S control points %s like SVG does', (_, d, explicit) => {
        expectReversed(reverseD(d), explicit);
    });

    test.each(['M5 6', 'M5 6Z', 'M1 2 M3 4', ''])('returns %p unchanged since it draws nothing', d => {
        expect(reverseD(d)).toBe(d);
    });
});

describe('startPoint', () => {
    test('is the start of the first drawing segment', () => {
        expect(startPoint('M100 100 M5 6 L10 10')).toBe('(5.000000, 6.000000)');
        expect(startPoint('M-1 -2.5 L10 0')).toBe('(-1.000000, -2.500000)');
        expect(startPoint('M10 10 Z l5 5')).toBe('(10.000000, 10.000000)');
    });

    test('shows the origin as coordinates', () => {
        expect(startPoint('M0 0 L10 0')).toBe('(0.000000, 0.000000)');
    });

    test.each([null, '', 'M5 6'])('is N/A for %p', d => {
        expect(startPoint(d)).toBe('N/A');
    });
});

describe('parseTimingClasses', () => {
    test('splits animation values from ordinary classes', () => {
        expect(parseTimingClasses('letter duration-0_5 delay-0_3 ease-power1_inOut')).toEqual({
            class: 'letter',
            duration: '0.5',
            delay: '0.3',
            easing: 'power1.inOut',
        });
    });

    test('keeps duplicate ordinary classes, lets the last timing class win and keeps "0"', () => {
        expect(parseTimingClasses('keep keep animate duration-2 duration-1_5 delay-0')).toEqual({
            class: 'keep keep animate',
            duration: '1.5',
            delay: '0',
        });
    });

    test('drops empty timing values', () => {
        expect(parseTimingClasses('keep duration-1 duration- delay- ease-')).toEqual({ class: 'keep' });
        expect(parseTimingClasses(null)).toEqual({});
    });
});

describe('timingClasses', () => {
    test('replaces existing timing classes and keeps "0" values', () => {
        const timing = { duration: '0', delay: '0', easing: 'power2.inOut' };
        expect(timingClasses('keep keep animate duration-2 delay-1 ease-power1_out', timing))
            .toBe('keep keep animate duration-0 delay-0 ease-power2_inOut');
    });

    test('removes timing classes of paths without values', () => {
        expect(timingClasses('untouched duration-9', undefined)).toBe('untouched');
        expect(timingClasses('duration-3 delay-2 ease-bounce_out', { duration: '', delay: '', easing: '' })).toBeNull();
        expect(timingClasses(null, {})).toBeNull();
    });
});

import { defineConfig } from 'vite';
import tailwindcss from '@tailwindcss/vite';

export default defineConfig({
    plugins: [tailwindcss()],
});

// SVG processing for the browser: path extraction, path reversal with animation
// classes, and the downloadable animation zip.

import { parsePathString, reversePath, pathToString } from 'svg-path-commander/util';
import { zipSync, strToU8 } from 'fflate';

const SVG_NS = 'http://www.w3.org/2000/svg';
const XMLNS_NS = 'http://www.w3.org/2000/xmlns/';
const SVG_PLACEHOLDER = '<!-- SVG_PLACEHOLDER -->';
const SCALE_STATEMENT = 'const animationScale = 1;';
const TIMING_PREFIXES = { duration: 'duration-', delay: 'delay-', easing: 'ease-' };

// Normalizes close-delimited chunks once, carrying the subpath start into the
// next chunk. The leading M lets the parser accept commands after Z and keeps
// relative m relative to that start; it is discarded if the chunk has its own M.
function segmentsOf(d) {
    let x = 0, y = 0;
    return d.split(/(?<=[Zz])/).flatMap((chunk, index) => {
        const segments = normalize(index === 0 ? chunk : `M${x} ${y}${chunk}`);
        const start = segments.findLast(([command]) => command === 'M');
        if (start) [, x, y] = start;
        return index > 0 && /^[\s,]*(?:[Mm]|$)/.test(chunk) ? segments.slice(1) : segments;
    });
}

// Converts path data to absolute M, L, C, Q, A and Z segments. S and T are expanded
// here because svg-path-commander 2.3.3 reflects S control points wrongly after a
// Q or A segment, or when the previous control point has a coordinate of 0.
function normalize(d) {
    let x = 0, y = 0, mx = 0, my = 0, cx = 0, cy = 0, qx = 0, qy = 0, last = '';
    return parsePathString(d).map(([command, ...values]) => {
        const type = command.toUpperCase();
        const [dx, dy] = command === type ? [0, 0] : [x, y];
        const points = values.map((n, i) => n + (i % 2 ? dy : dx));
        let segment;
        if (type === 'H') segment = ['L', values[0] + dx, y];
        else if (type === 'V') segment = ['L', x, values[0] + dy];
        else if (type === 'S') segment = ['C', ...(last === 'C' || last === 'S' ? [2 * x - cx, 2 * y - cy] : [x, y]), ...points];
        else if (type === 'T') segment = ['Q', ...(last === 'Q' || last === 'T' ? [2 * x - qx, 2 * y - qy] : [x, y]), ...points];
        else if (type === 'A') segment = ['A', ...values.slice(0, 5), values[5] + dx, values[6] + dy];
        else if (type === 'Z') segment = ['Z'];
        else segment = [type, ...points];

        [x, y] = type === 'Z' ? [mx, my] : segment.slice(-2);
        if (type === 'M') [mx, my] = [x, y];
        if (segment[0] === 'C') [cx, cy] = segment.slice(3, 5);
        if (segment[0] === 'Q') [qx, qy] = segment.slice(1, 3);
        last = type;
        return segment;
    });
}

const isDrawing = ([command]) => command !== 'M' && command !== 'Z';

// Reverses the drawing direction of path data like svgpathtools' Path.reversed():
// subpaths run last to first and each one is traversed backwards. A closed subpath
// starts at its original start point and keeps its Z. Path data without any
// drawing segment (empty or moveto only) is returned unchanged.
export function reverseD(d) {
    const segments = segmentsOf(d);
    if (!segments.some(isDrawing)) return d;
    const subpaths = segments.reduce((list, segment) => {
        if (segment[0] === 'M') list.push([segment]);
        else list.at(-1).push(segment);
        return list;
    }, []);
    const reversed = subpaths.map(subpath => {
        if (subpath.at(-1)[0] !== 'Z') return reversePath(subpath);
        const [, x, y] = subpath[0];
        const open = subpath.slice(0, -1);
        const [ex, ey] = open.at(-1).slice(-2);
        if (ex !== x || ey !== y) open.push(['L', x, y]);
        return [...reversePath(open), ['Z']];
    });
    return pathToString(reversed.reverse().flat(), 'off');
}

// Formats the start of the first drawing segment as "(x, y)" with six decimals,
// or "N/A" when the path data is missing or draws nothing.
export function startPoint(d) {
    if (!d) return 'N/A';
    const segments = segmentsOf(d);
    const first = segments.findIndex(isDrawing);
    if (first < 0) return 'N/A';
    const [x, y] = segments[first - 1].slice(-2);
    return `(${x.toFixed(6)}, ${y.toFixed(6)})`;
}

const splitClasses = classString => (classString ?? '').split(/\s+/).filter(Boolean);
const isTimingClass = cls => Object.values(TIMING_PREFIXES).some(prefix => cls.startsWith(prefix));

// Reads a class attribute into the ordinary classes and the animation values of
// duration-*, delay-* and ease-* classes (last one wins, "_" read as "."). Keys
// are only present when they have a non-empty value.
export function parseTimingClasses(classString) {
    const classes = splitClasses(classString);
    const result = {};
    const ordinary = classes.filter(cls => !isTimingClass(cls));
    if (ordinary.length) result.class = ordinary.join(' ');
    for (const [key, prefix] of Object.entries(TIMING_PREFIXES)) {
        const value = classes.findLast(cls => cls.startsWith(prefix))?.slice(prefix.length).replaceAll('_', '.');
        if (value) result[key] = value;
    }
    return result;
}

// Rewrites a class attribute: existing timing classes are replaced by the given
// duration, delay and easing ("." written as "_"). Returns null when no class is left.
export function timingClasses(existingClass, timing = {}) {
    const classes = splitClasses(existingClass).filter(cls => !isTimingClass(cls));
    for (const [key, prefix] of Object.entries(TIMING_PREFIXES)) {
        if (timing[key]) classes.push(prefix + timing[key].replaceAll('.', '_'));
    }
    return classes.length ? classes.join(' ') : null;
}

const parseXml = text => new DOMParser().parseFromString(text, 'image/svg+xml');
const parseErrorOf = doc => doc.getElementsByTagName('parsererror')[0];

// Parses SVG text into an XML document. Input whose root is not <svg>, such as a
// bare <path>, is wrapped in an <svg> element. Throws with the parser's message
// on malformed XML.
export function parseSvg(text) {
    const doc = parseXml(text);
    const error = parseErrorOf(doc);
    if (!error && doc.documentElement.localName === 'svg') return doc;
    const wrapped = parseXml(`<svg xmlns="${SVG_NS}">${text}</svg>`);
    const wrappedError = parseErrorOf(wrapped);
    if (!wrappedError) return wrapped;
    const report = error ?? wrappedError;
    throw new Error((report.querySelector('div') ?? report).textContent.trim());
}

// All <path> elements in the SVG namespace or in no namespace, in document order.
const pathsOf = doc => [...doc.documentElement.getElementsByTagName('*')]
    .filter(el => el.localName === 'path' && (el.namespaceURI === SVG_NS || el.namespaceURI === null));

const serialize = doc => new XMLSerializer().serializeToString(doc);

// Lists the paths of an SVG with their start point, attributes and animation
// values. Returns { paths, svg } where svg is the parsed SVG serialized again.
export function extractPaths(svgText) {
    const doc = parseSvg(svgText);
    const paths = pathsOf(doc).map((path, index) => {
        const d = path.getAttribute('d');
        const id = path.getAttribute('id');
        const attributes = Object.fromEntries([...path.attributes]
            .filter(attr => attr.namespaceURI !== XMLNS_NS)
            .map(attr => [attr.namespaceURI ? `{${attr.namespaceURI}}${attr.localName}` : attr.name, attr.value]));
        return {
            d,
            start: startPoint(d),
            attributes,
            index,
            ...(id && { id }),
            ...parseTimingClasses(path.getAttribute('class')),
        };
    });
    return { paths, svg: serialize(doc) };
}

// Reverses the paths at the given indexes and writes the animation classes of
// every path from pathData ([{ index, duration, delay, easing }]); paths without
// an entry lose their timing classes. Returns the updated SVG text.
export function reversePaths(svgText, indexes, pathData = []) {
    const doc = parseSvg(svgText);
    const selected = new Set(indexes.map(Number));
    const timing = new Map(pathData.map(item => [Number(item.index), item]));
    pathsOf(doc).forEach((path, index) => {
        if (selected.has(index)) {
            const d = path.getAttribute('d');
            if (d === null) throw new Error(`Path ${index} has no d attribute`);
            path.setAttribute('d', reverseD(d));
        }
        const classes = timingClasses(path.getAttribute('class'), timing.get(index));
        if (classes) path.setAttribute('class', classes);
        else path.removeAttribute('class');
    });
    return serialize(doc);
}

// Fetches a static text file and checks it is the expected one, since unknown
// paths are answered with the app's index.html.
async function fetchStatic(url, marker) {
    const res = await fetch(url);
    const text = res.ok ? await res.text() : '';
    if (!text.includes(marker)) throw new Error(`Could not load ${url}`);
    return text;
}

// Builds the downloadable animation: a zip Blob with anim.mjs and an index.html
// that embeds the SVG and plays it at the given speed scale.
export async function buildZip(svg, scale) {
    if (!svg) throw new Error('Modified SVG not provided');
    if (!scale) throw new Error('Animation scale not provided');
    const [anim, template] = await Promise.all([
        fetchStatic('/static/js/anim.mjs', 'animateSVGPaths'),
        fetchStatic('/static/zip_files/index.html', SVG_PLACEHOLDER),
    ]);
    const html = template
        .replaceAll(SVG_PLACEHOLDER, () => svg)
        .replaceAll(SCALE_STATEMENT, () => `const animationScale = ${scale};`);
    const zip = zipSync({ 'anim.mjs': strToU8(anim), 'index.html': strToU8(html) });
    return new Blob([zip], { type: 'application/zip' });
}

import $ from 'jquery';
import ace from 'ace-builds';
import 'ace-builds/src-noconflict/mode-svg';
import 'ace-builds/src-noconflict/theme-dracula';
import 'ace-builds/src-noconflict/ext-searchbox';
import 'ace-builds/src-noconflict/ext-prompt';
import 'ace-builds/src-noconflict/ext-settings_menu';
import { gsap } from 'gsap';
import Swal from 'sweetalert2/dist/sweetalert2.esm.js';
import './styles.css';
import { buildZip, extractPaths, reversePaths } from './svg.js';

// Settings loads themes, modes and keybindings on demand. Keep those choices
// and their workers available locally instead of relying on Ace's former CDN.
const aceAssets = import.meta.glob('../node_modules/ace-builds/src-min-noconflict/{theme,mode,keybinding,worker}-*.js', {
    eager: true,
    query: '?url&no-inline',
    import: 'default',
});
for (const [file, url] of Object.entries(aceAssets)) {
    const [, type, name] = file.match(/\/(theme|mode|keybinding|worker)-(.+)\.js$/);
    const module = type === 'worker' ? `ace/mode/${name}_worker`
        : `ace/${type === 'keybinding' ? 'keyboard' : type}/${name}`;
    ace.config.setModuleUrl(module, url);
}

// Keep the standalone animation script identical to the copy in downloads.
// Only animation controls wait for it; editing still works if loading fails.
window.gsap = gsap;
const animationButtons = $('#animate-original, #animate-edited').prop('disabled', true);
const animationScript = document.createElement('script');
animationScript.src = '/static/js/anim.mjs';
animationScript.onload = () => {
    animationButtons.prop('disabled', typeof window.animateSVGPaths !== 'function');
};
animationScript.onerror = () => {
    animationButtons.attr('title', 'Animation preview is unavailable. Reload to try again.');
};
document.head.append(animationScript);

// Default SVG for the input editor, empty if it cannot be loaded
const defaultSvg = await fetch('/static/svg/hello.svg')
    .then(res => (res.ok ? res.text() : ''))
    .catch(() => '');

// Initialize Ace Editor for the input
let editor = ace.edit("input-editor");
editor.setTheme("ace/theme/dracula");
editor.session.setMode("ace/mode/svg");
editor.setValue(defaultSvg, -1); // Set initial content
editor.renderer.setShowPrintMargin(false); // Remove the gray line

// Initialize Ace Editor for the output (result)
let resultEditor = ace.edit("output-editor");
resultEditor.setTheme("ace/theme/dracula");
resultEditor.session.setMode("ace/mode/svg");
resultEditor.setReadOnly(true); // Make the editor read-only
resultEditor.renderer.setShowPrintMargin(false); // Remove the gray line

// this array will store the indexes of paths that are reversed
let reversedPaths = [];

// variables to store SVG content
let originalSvg = '';
let modifiedSvg = '';

// Variable to store the animation scale
let animationScale = 1; // Default scale

// Define arrays for easing functions and types
const easingFunctions = [
    'linear',
    'power1',
    'power2',
    'power3',
    'power4',
    'back',
    'bounce',
    'circ',
    'elastic',
    'expo',
    'sine',
    'steps'
];

const easingTypes = ['.in', '.out', '.inOut'];

$('#parse-btn').on('click', function () {
    const svgCode = editor.getValue();

    // Check if the SVG code is empty
    if (svgCode.trim() === "") {
        showSwal('No SVG code', 'Please enter an SVG code!', false);
        return;
    }
    originalSvg = svgCode;
    let data;
    try {
        ({ paths: data, svg: originalSvg } = extractPaths(svgCode));
    } catch (error) {
        showSwal('Error', 'Error parsing the SVG!\n' + error.message, false);
        // Track parsing error
        if (typeof umami !== 'undefined') {
            umami.track('processing_error', {
                error_type: 'parse',
                error_message: 'svg_parse_failed',
                svg_size: svgCode.length > 10000 ? 'large' : svgCode.length > 2000 ? 'medium' : 'small'
            });
        }
        return;
    }
    $('#path-list').empty();
    reversedPaths = [];  // Reset reversed paths on each parse

    // Check if any paths are found in the SVG
    if (data.length === 0) {
        showSwal('No Paths Found', 'No paths found in the SVG!', false);
        showResultUI(false);
        // Track parsing failure
        if (typeof umami !== 'undefined') {
            umami.track('processing_error', {
                error_type: 'parse',
                error_message: 'no_paths_found',
                svg_size: svgCode.length > 10000 ? 'large' : svgCode.length > 2000 ? 'medium' : 'small'
            });
        }
        return;
    }

    showResultUI(true);

    data.forEach(function (path, index) {
        const checkbox = `<input type="checkbox" id="path${index}" value="${index}" class="checkbox checkbox-xl" checked>`;
        const statusBadge = `<span id="status${index}" class="badge badge-success badge-lg w-24 text-center m-1">reversed</span>`;
        let pathIdBadge = '';
        let pathClassBadge = '';
        // Get duration and delay from path
        let durationValue = path.duration || '';
        let delayValue = path.delay || '';
        const animationDurationInput = `<div class="tooltip" data-tip="duration"><input type="text" value="${durationValue}" placeholder="2" class="input-duration input input-accent input-sm w-20 text-center" /></div>`;
        const animationDelayInput = `<div class="tooltip" data-tip="delay"><input type="text" value="${delayValue}" placeholder="0" class="input-delay input input-accent input-sm w-20 text-center" /></div>`;

        // id badge
        if (path.id) {
            pathIdBadge = `<span class="badge badge-secondary badge-lg">#${path.id}</span>`;
        }
        // class badge
        if (path.class) {
            // Filter out 'duration-*', 'delay-*', and 'animate' classes
            let filteredClasses = path.class.split(' ').filter(cls => {
                return !cls.startsWith('duration-') && !cls.startsWith('delay-') && cls !== 'animate';
            }).join(' ');
            if (filteredClasses) {
                pathClassBadge = `<span class="badge badge-primary badge-lg ml-1 whitespace-nowrap">${filteredClasses}</span>`;
            }
        }
        // start value badge - only show for paths without an ID
        let startBadge = '';
        if (!path.id && path.start) {
            // Parse the coordinates and format with 2 decimal places
            const coords = path.start.match(/[\d.]+/g);
            if (coords && coords.length >= 2) {
                const x = parseFloat(coords[0]).toFixed(2);
                const y = parseFloat(coords[1]).toFixed(2);
                const startValue = `(${x}, ${y})`;
                startBadge = `<span class="badge badge-info badge-lg ml-1 text-nowrap">${startValue}...</span>`;
            }
        }

        // Get easing from path
        let easingValue = path.easing || '';
        let easingFunction = '';
        let easingType = '';
        if (easingValue) {
            let parts = easingValue.split('.');
            easingFunction = parts[0]; // e.g., 'power2'
            easingType = parts[1] ? '.' + parts[1] : ''; // e.g., '.out'
        }

        // Create easing function options
        function createEasingFunctionOptions(selectedFunction) {
            return easingFunctions.map(function (easeFunc) {
                let selected = (easeFunc === selectedFunction || (!selectedFunction && easeFunc === 'power1')) ? 'selected' : '';
                return `<option value="${easeFunc}" ${selected}>${easeFunc}</option>`;
            }).join('');
        }

        // Create easing type options
        function createEasingTypeOptions(selectedType) {
            return easingTypes.map(function (easeType) {
                let label = easeType.replace('.', '') || 'out'; // Default to 'out' if empty
                let selected = (easeType === selectedType || (!selectedType && easeType === '.out')) ? 'selected' : '';
                return `<option value="${easeType}" ${selected}>${label}</option>`;
            }).join('');
        }

        const easingFunctionSelect = `<div class="tooltip" data-tip="easing function"><select class="select-easing-function select select-accent select-sm">
        ${createEasingFunctionOptions(easingFunction)}
        </select></div>`;

        const easingTypeSelect = `<div class="tooltip" data-tip="easing type"><select class="select-easing-type select select-accent select-sm">
        ${createEasingTypeOptions(easingType)}
        </select></div>`;

        // Append the path item with the new selects
        $('#path-list').append(`
            <div class="path-item flex flex-col sm:flex-row gap-2 py-2">
                <div class="flex items-center gap-2">
                    ${checkbox}
                    ${statusBadge}
                    <div class="flex items-center gap-2 min-w-0">
                        ${pathIdBadge}
                        ${pathClassBadge}
                        ${startBadge}
                    </div>
                </div>
                <div class="flex items-center gap-1 sm:ml-auto">
                    ${animationDurationInput}
                    ${animationDelayInput}
                    ${easingFunctionSelect}
                    ${easingTypeSelect}
                </div>
            </div>
        `);

        // Add path index to reversedPaths
        reversedPaths.push(index);
    });

    // Show the original SVG until the reversal below replaces it
    resultEditor.setValue(originalSvg, -1);
    $('#svg-preview').html(originalSvg);

    // Update the SVG with all paths reversed
    updateSvgWithReversedPaths();

    // Track successful SVG parsing
    if (typeof umami !== 'undefined') {
        const hasClasses = data.some(path => path.class);
        const hasIds = data.some(path => path.id);
        const hasAnimationClasses = data.some(path => path.duration || path.delay || path.easing);

        umami.track('svg_parsed', {
            paths_found: data.length,
            has_classes: hasClasses,
            has_ids: hasIds,
            has_animation_classes: hasAnimationClasses,
            svg_size: svgCode.length > 10000 ? 'large' : svgCode.length > 2000 ? 'medium' : 'small'
        });
    }
});

